import{z as A,x as i,o as t,c as d,q as o,j as B,D as e,d as l,s as r,S as s,b as E}from"./chunks/framework.C8m1ZpeB.js";const c=JSON.parse('{"title":"注意力头的功能分化","description":"","frontmatter":{"title":"注意力头的功能分化","date":"2026-09-08T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/attention-head-roles.md","filePath":"llm/attention-head-roles.md","lastUpdated":1791063341000}'),p={name:"llm/attention-head-roles.md"};function h(m,a,C,D,f,u){const n=i("Mermaid");return t(),d("div",null,[a[2]||(a[2]=o('<h1 id="注意力头的功能分化" tabindex="-1">注意力头的功能分化 <a class="header-anchor" href="#注意力头的功能分化" aria-label="Permalink to &quot;注意力头的功能分化&quot;">​</a></h1><div class="epigraph"><p>多头不是重复的备份；有的头盯句法边，有的头几乎均匀，关掉一部分往往损失很小。</p><footer>—— Voita et al., Analyzing Multi-Head Self-Attention, ACL 2019；Clark et al., What Does BERT Look At?, BlackboxNLP 2019</footer></div><p><a href="/llm/attention-length-scaling">上一课</a>让同一套分数在不同长度上峰度可校准。本课问这些头<strong>在校准之后各自干什么</strong>。主干 <a href="/llm/mha">多头</a> 只给切分，不给语义。<a href="/llm/head-dim-vs-heads">头维对头数</a> 只给容量分配。解释与剪枝要用的是功能：位置头、句法头、归纳头、几乎死掉的头。后课 Universal Transformer 把「一层」循环起来，默认你接受「头已经分化，深度用来叠功能而不是复制同一头」。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>可视化权重常让人以为每个头都在做重要对齐。Voita 等人对机器翻译、Clark 等人对 BERT 编码器都看到：少数头承担可命名的关系（相邻、指代、动词宾语），大量头权重平坦或与其它头高度相关。缺口是把这件事写成设计约束——<strong>多头提供的是功能槽位，槽位会被填满、冗余、或闲置</strong>，加头不等于加功能。</p><p><a href="/llm/induction-heads">归纳头</a> 是解码器里后来被钉死的一种电路。本课不重做那一课的实验，只把「功能分化」接到编码器与解码器共用的多头事实上，并标明可视化权重不等于贡献——<a href="/llm/sdpa">SDPA</a> 课已经警告过值向量。</p><p><span class="marginnote">前缀掩码、双向编码器里，头还可以分化出「读右侧」与「读左侧」。因果栈没有右侧，分化发生在距离、内容类型与是否拷贝上。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>分析手段三层，由浅到深。第一，看 \\(A=\\mathrm{softmax}(S)\\) 的平均注意力距离、熵、指向特殊 token 的质量（汇）。第二，把单头置零或只留单头，测任务跌点，得到头的边际贡献。第三，构造或引用已知电路（归纳、抑制、上一 token），在残差流里做路径补丁。编码器侧 Clark 的「看什么」属于第一层加语言学探针；Voita 的剪头属于第二层。</p><p><span class="marginnote">术语翻译：「熵」在这里衡量一个头的注意力摊得多开——熵接近 0 说明它把全部权重押在一两个位置上（尖峰检索），熵接近 \\(\\log n\\) 说明它几乎均匀地扫全场。「汇」指的是不少头喜欢把一大块质量固定扔给 BOS 之类的特殊 token，像是给多余的注意力找一个下水口。</span></p><p>训练中途头的功能会迁移，早停的可视化不能当最终电路。比较功能前应固定长度缩放与是否门控，否则汇头与内容头会互相污染。</p>',11)),(t(),B(s,null,{default:e(()=>[r(n,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20H%5B%22%E5%BE%85%E5%88%86%E6%9E%90%E7%9A%84%E5%A4%B4%22%5D%20--%3E%20L1%5B%22%E7%AC%AC%E4%B8%80%E5%B1%82%EF%BC%9A%E5%8F%AA%E7%9C%8B%E6%9D%83%E9%87%8D%E7%BB%9F%E8%AE%A1%EF%BC%88%E8%B7%9D%E7%A6%BB%E3%80%81%E7%86%B5%E3%80%81%E6%8C%87%E5%90%91%E6%B1%87%EF%BC%89%22%5D%0A%20%20L1%20--%3E%20C1%5B%22%E4%BE%BF%E5%AE%9C%E4%BD%86%E6%9C%89%E5%81%87%E9%98%B3%E6%80%A7%EF%BC%9A%E5%8F%AA%E6%8F%8F%E8%BF%B0%E4%B8%8D%E8%AF%81%E6%98%8E%22%5D%0A%20%20H%20--%3E%20L2%5B%22%E7%AC%AC%E4%BA%8C%E5%B1%82%EF%BC%9A%E7%BD%AE%E9%9B%B6%20%2F%20%E5%8F%AA%E7%95%99%E5%8D%95%E5%A4%B4%E6%B5%8B%E8%B7%8C%E7%82%B9%22%5D%0A%20%20L2%20--%3E%20C2%5B%22%E5%BE%97%E5%88%B0%E8%BE%B9%E9%99%85%E8%B4%A1%E7%8C%AE%EF%BC%8C%E5%8F%AF%E6%8C%87%E5%AF%BC%E5%89%AA%E6%9E%9D%22%5D%0A%20%20H%20--%3E%20L3%5B%22%E7%AC%AC%E4%B8%89%E5%B1%82%EF%BC%9A%E6%9E%84%E9%80%A0%E5%B7%B2%E7%9F%A5%E7%94%B5%E8%B7%AF%E5%81%9A%E8%B7%AF%E5%BE%84%E8%A1%A5%E4%B8%81%22%5D%0A%20%20L3%20--%3E%20C3%5B%22%E5%9B%A0%E6%9E%9C%E8%AF%81%E6%8D%AE%EF%BC%8C%E6%88%90%E6%9C%AC%E6%9C%80%E9%AB%98%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[l(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=o('<h3 id="冗余的两种来源" tabindex="-1">冗余的两种来源 <a class="header-anchor" href="#冗余的两种来源" aria-label="Permalink to &quot;冗余的两种来源&quot;">​</a></h3><p>一种是优化：多个头学到几乎同一套路由，剪掉一个另一个顶上。一种是宽度：头维太薄，谁也学不成稳定功能，看起来像噪声头。应对不同——前者可剪，后者应加 \\(d_k\\) 或减 \\(h\\)，回到上一课的分配。</p><p><span class="marginnote">常见误区：把「看起来没规律的头」一律当冗余剪掉。这两种冗余的处方相反——重复路由的头删了没事；头维太薄的「噪声头」剪掉只是丢掉没长成的槽位，正确做法是回设计层改 \\(h\\) 与 \\(d_k\\) 的分配。剪之前先用第二层手段确认是哪一种。</span></p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>Softmax 的竞争在头内发生，头间只在输出投影处相加。这允许同时存在尖峰检索头与近均匀混合头。残差流把它们的值加在一起，下游 FFN 再读混合物。功能分化因此是「并行专家式的读」，不是层间的串行流水线——串行发生在层与层之间，那是下一课循环深度要动的轴。</p><p><span class="marginnote">直觉类比：头间相加像一间办公室里几位分析员同时交报告——检索尖峰的那位只递一句话结论，近均匀的那位交一份全景综述，FFN 是把所有报告合起来下判断的主管。每位分析员独立工作（头内竞争、头间不抢），最后只是把成果加在一起。</span></p><p>注意力汇可以是一种退化功能：把强制质量扔给 BOS，好让其它头少受行和约束。门控或 sigmoid 会改变这种退化是否还必要。解释头时要声明归一化假设。</p><p><span class="marginnote">「这个头在复制上一 token」是对电路的陈述，需要对值向量与输出投影做因果干预才能坐实。只看权重亮在对角线上，不够。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>功能标签不可移植到任意检查点：同结构不同数据，头的分工会换。不要在课序里把 BERT 的句法头当成 GPT 的归纳头。剪头是部署优化，不是训练目标；训练时用头级 dropout 可以鼓励分化，也会伤优化。下一课开始把同一组参数沿深度重复使用，分化的槽位会从「第 \\(\\ell\\) 层第 \\(h\\) 头」变成「第 \\(t\\) 次循环第 \\(h\\) 头」，索引方式要改。</p>',10)),(t(),B(s,null,{default:e(()=>[r(n,{id:"mermaid-62",class:"mermaid",graph:"flowchart%20TD%0A%20%20H%5B%22%E8%8B%A5%E5%B9%B2%E5%A4%B4%E5%B9%B6%E8%A1%8C%22%5D%20--%3E%20A%5B%22%E5%B0%96%E5%B3%B0%E6%A3%80%E7%B4%A2%22%5D%0A%20%20H%20--%3E%20B%5B%22%E5%B1%80%E9%83%A8%E5%8F%A5%E6%B3%95%22%5D%0A%20%20H%20--%3E%20C%5B%22%E8%BF%91%E5%9D%87%E5%8C%80%E6%B7%B7%E5%90%88%22%5D%0A%20%20H%20--%3E%20D%5B%22%E6%B1%87%E5%88%B0%E7%89%B9%E6%AE%8A%20token%22%5D%0A%20%20A%20--%3E%20O%5B%22%E8%BE%93%E5%87%BA%E6%8A%95%E5%BD%B1%E7%9B%B8%E5%8A%A0%22%5D%0A%20%20B%20--%3E%20O%0A%20%20C%20--%3E%20O%0A%20%20D%20--%3E%20O%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[l(" Loading... ",-1)])]),_:1})),a[4]||(a[4]=E("h2",{id:"小结",tabindex:"-1"},[l("小结 "),E("a",{class:"header-anchor",href:"#小结","aria-label":'Permalink to "小结"'},"​")],-1)),a[5]||(a[5]=E("ul",null,[E("li",null,"多头提供功能槽位；槽位会被填成可命名电路，也会冗余或闲置。"),E("li",null,"分析要分层：权重统计、置零跌点、路径补丁；只看权重会误判。"),E("li",null,"冗余头可剪，噪声头应回头改 \\(h\\) 与 \\(d_k\\)，不要混为一谈。"),E("li",null,"功能标签绑定检查点与掩码，不能跨架构复述。"),E("li",null,"出处：Voita et al., ACL 2019；Clark et al., 2019。")],-1))])}const _=A(p,[["render",h]]);export{c as __pageData,_ as default};
